-- views.sql — הגדרות התצוגות של הקטלוג (DuckDB). נוצר אוטומטית על ידי engines/pull_options.py — לא לערוך ידנית.
-- תיעוד: catalog/open_catalog.py מריץ את אותן הגדרות בדיוק, כש-<OPTIONS_DIR> ו-<MARKET_DIR> מוחלפים בנתיבים מוחלטים שנפתרים
-- ברגע הקריאה (<OPTIONS_DIR> — שורש trading-options-data; <MARKET_DIR> — שורש trading-market-data, העותק האח).
-- תצוגה שאין לה קבצים נוצרת ריקה, עם כל העמודות (ההגדרה שבהערה "אין קבצים").
SET TimeZone='America/New_York';

-- options_eod: שרשראות סוף-יום אחרי הסינון — מאגר האופציות, `eod/<סמל>/<שנה-חודש>.parquet`
CREATE OR REPLACE VIEW options_eod AS SELECT underlying AS symbol, * FROM read_parquet('<OPTIONS_DIR>/eod/*/*.parquet', union_by_name=true);
-- אין קבצים: CREATE OR REPLACE VIEW options_eod AS SELECT NULL::VARCHAR AS "symbol", NULL::VARCHAR AS "option_symbol", NULL::VARCHAR AS "underlying", NULL::DATE AS "session", NULL::DATE AS "expiration", NULL::VARCHAR AS "side", NULL::DOUBLE AS "strike", NULL::DOUBLE AS "bid", NULL::DOUBLE AS "ask", NULL::DOUBLE AS "mid", NULL::BIGINT AS "bid_size", NULL::BIGINT AS "ask_size", NULL::DOUBLE AS "open", NULL::DOUBLE AS "high", NULL::DOUBLE AS "low", NULL::DOUBLE AS "close", NULL::BIGINT AS "volume", NULL::BIGINT AS "trades", NULL::DOUBLE AS "open_interest", NULL::BOOLEAN AS "oi_asof_prev_close", NULL::BOOLEAN AS "crossed", NULL::TIMESTAMP WITH TIME ZONE AS "quote_time", NULL::TIMESTAMP WITH TIME ZONE AS "last_trade", NULL::TIMESTAMP WITH TIME ZONE AS "created", NULL::BIGINT AS "dte", NULL::DOUBLE AS "T_years", NULL::DOUBLE AS "risk_free", NULL::DOUBLE AS "iv_calc", NULL::DOUBLE AS "delta_calc", NULL::VARCHAR AS "kept_by", NULL::BIGINT AS "filter_version", NULL::DOUBLE AS "spot_raw", NULL::VARCHAR AS "spot_source", NULL::VARCHAR AS "price_basis", NULL::VARCHAR AS "model_version" WHERE 1=0;

-- options_intraday: תמונות שרשרת בנקודות קבועות ביום, אחרי הסינון — מאגר האופציות, `intraday/<סמל>/<שנה-חודש>.parquet`
CREATE OR REPLACE VIEW options_intraday AS SELECT underlying AS symbol, * FROM read_parquet('<OPTIONS_DIR>/intraday/*/*.parquet', union_by_name=true);
-- אין קבצים: CREATE OR REPLACE VIEW options_intraday AS SELECT NULL::VARCHAR AS "symbol", NULL::VARCHAR AS "option_symbol", NULL::VARCHAR AS "underlying", NULL::DATE AS "session", NULL::DATE AS "expiration", NULL::VARCHAR AS "side", NULL::DOUBLE AS "strike", NULL::DOUBLE AS "bid", NULL::DOUBLE AS "ask", NULL::DOUBLE AS "mid", NULL::BIGINT AS "bid_size", NULL::BIGINT AS "ask_size", NULL::BOOLEAN AS "crossed", NULL::TIMESTAMP WITH TIME ZONE AS "snapshot_time", NULL::TIMESTAMP WITH TIME ZONE AS "quote_time", NULL::DOUBLE AS "lag_sec", NULL::DOUBLE AS "open_interest", NULL::BOOLEAN AS "oi_asof_prev_close", NULL::VARCHAR AS "point", NULL::BIGINT AS "dte", NULL::DOUBLE AS "T_years", NULL::DOUBLE AS "risk_free", NULL::DOUBLE AS "iv_calc", NULL::DOUBLE AS "delta_calc", NULL::VARCHAR AS "kept_by", NULL::BIGINT AS "filter_version", NULL::DOUBLE AS "spot_raw", NULL::VARCHAR AS "spot_source", NULL::VARCHAR AS "price_basis", NULL::VARCHAR AS "model_version" WHERE 1=0;

-- candles_daily: נרות יומיים **מותאמים** לדיבידנד ולפיצול — מאגר נתוני השוק, `daily/<סמל>.csv`
CREATE OR REPLACE VIEW candles_daily AS SELECT regexp_extract(filename, '([A-Za-z0-9._-]+)\.(csv|parquet)$', 1) AS symbol, time_ny::DATE AS session, open, high, low, close, volume FROM read_csv('<MARKET_DIR>/daily/*.csv', header=true, filename=true, types={'time_ny': 'VARCHAR', 'open': 'DOUBLE', 'high': 'DOUBLE', 'low': 'DOUBLE', 'close': 'DOUBLE', 'volume': 'DOUBLE'});
-- אין קבצים: CREATE OR REPLACE VIEW candles_daily AS SELECT NULL::VARCHAR AS "symbol", NULL::DATE AS "session", NULL::DOUBLE AS "open", NULL::DOUBLE AS "high", NULL::DOUBLE AS "low", NULL::DOUBLE AS "close", NULL::DOUBLE AS "volume" WHERE 1=0;

-- candles_daily_raw: נרות יומיים **גולמיים** + גורם התאמה — מאגר נתוני השוק, `daily_raw/<סמל>.csv`
CREATE OR REPLACE VIEW candles_daily_raw AS SELECT regexp_extract(filename, '([A-Za-z0-9._-]+)\.(csv|parquet)$', 1) AS symbol, time_ny::DATE AS session, open, high, low, close, volume, adj_factor FROM read_csv('<MARKET_DIR>/daily_raw/*.csv', header=true, filename=true, types={'time_ny': 'VARCHAR', 'open': 'DOUBLE', 'high': 'DOUBLE', 'low': 'DOUBLE', 'close': 'DOUBLE', 'volume': 'DOUBLE', 'adj_factor': 'DOUBLE'});
-- אין קבצים: CREATE OR REPLACE VIEW candles_daily_raw AS SELECT NULL::VARCHAR AS "symbol", NULL::DATE AS "session", NULL::DOUBLE AS "open", NULL::DOUBLE AS "high", NULL::DOUBLE AS "low", NULL::DOUBLE AS "close", NULL::DOUBLE AS "volume", NULL::DOUBLE AS "adj_factor" WHERE 1=0;

-- candles_30m: נרות 30 דקות (גולמיים לדיבידנד, מותאמים לפיצול) — מאגר נתוני השוק, `intraday30/<סמל>.csv`; ב-`spot_raw` של התוך-יומי סגירת הנר **מוחזרת לבסיס הגולמי** מול הסגירה הגולמית של אותו יום (נ-1). **13 נרות ביום רגיל** (09:30 … 15:30 — אין נר של 16:00, ולכן סגירת הנר האחרון אינה תמיד הסגירה הרשמית) ו-**8 נרות ביום מקוצר** (האחרון — 13:00, הדפסת הנעילה); סכום הנפח של הנרות קטן מהנפח היומי
CREATE OR REPLACE VIEW candles_30m AS SELECT regexp_extract(filename, '([A-Za-z0-9._-]+)\.(csv|parquet)$', 1) AS symbol, time_ny::TIMESTAMPTZ AS time_ny, open, high, low, close, volume FROM read_csv('<MARKET_DIR>/intraday30/*.csv', header=true, filename=true, types={'time_ny': 'VARCHAR', 'open': 'DOUBLE', 'high': 'DOUBLE', 'low': 'DOUBLE', 'close': 'DOUBLE', 'volume': 'DOUBLE'});
-- אין קבצים: CREATE OR REPLACE VIEW candles_30m AS SELECT NULL::VARCHAR AS "symbol", NULL::TIMESTAMP WITH TIME ZONE AS "time_ny", NULL::DOUBLE AS "open", NULL::DOUBLE AS "high", NULL::DOUBLE AS "low", NULL::DOUBLE AS "close", NULL::DOUBLE AS "volume" WHERE 1=0;

-- vix_family: משפחת ה-VIX (CBOE), יומי — מאגר נתוני השוק, `cboe/<מדד>.csv`. **ל-VIX יש שורות גם בימים שהבורסה למניות סגורה** — "N סשנים אחורה" לפי לוח המסחר (`candles_daily` של SPY — חמש שנים; `candles_daily_raw` מתחיל רק ב-02/10/2023), לא לפי השורות; **ל-VVIX סגירה בלבד** (פתיחה, שיא ושפל ריקים)
CREATE OR REPLACE VIEW vix_family AS SELECT regexp_extract(filename, '([A-Za-z0-9._-]+)\.(csv|parquet)$', 1) AS symbol, time_ny::DATE AS session, open, high, low, close FROM read_csv('<MARKET_DIR>/cboe/*.csv', header=true, filename=true, types={'time_ny': 'VARCHAR', 'open': 'DOUBLE', 'high': 'DOUBLE', 'low': 'DOUBLE', 'close': 'DOUBLE'});
-- אין קבצים: CREATE OR REPLACE VIEW vix_family AS SELECT NULL::VARCHAR AS "symbol", NULL::DATE AS "session", NULL::DOUBLE AS "open", NULL::DOUBLE AS "high", NULL::DOUBLE AS "low", NULL::DOUBLE AS "close" WHERE 1=0;

-- corporate_actions: פיצולים — מאגר האופציות, `corporate_actions.csv`
CREATE OR REPLACE VIEW corporate_actions AS SELECT * FROM read_csv('<OPTIONS_DIR>/corporate_actions.csv', header=true, types={'symbol': 'VARCHAR', 'date': 'DATE', 'ratio': 'DOUBLE', 'source': 'VARCHAR', 'verified': 'VARCHAR', 'verified_by': 'VARCHAR', 'note': 'VARCHAR'});
-- אין קבצים: CREATE OR REPLACE VIEW corporate_actions AS SELECT NULL::VARCHAR AS "symbol", NULL::DATE AS "date", NULL::DOUBLE AS "ratio", NULL::VARCHAR AS "source", NULL::VARCHAR AS "verified", NULL::VARCHAR AS "verified_by", NULL::VARCHAR AS "note" WHERE 1=0;

-- contracts_watch: חוזים במעקב — נשמרים עד פקיעתם גם מחוץ למסננים; מאגר האופציות, `contracts_watch.csv`
CREATE OR REPLACE VIEW contracts_watch AS SELECT * FROM read_csv('<OPTIONS_DIR>/contracts_watch.csv', header=true, types={'option_symbol': 'VARCHAR', 'underlying': 'VARCHAR', 'expiration': 'DATE', 'side': 'VARCHAR', 'strike': 'DOUBLE', 'added_ny': 'VARCHAR', 'note': 'VARCHAR'});
-- אין קבצים: CREATE OR REPLACE VIEW contracts_watch AS SELECT NULL::VARCHAR AS "option_symbol", NULL::VARCHAR AS "underlying", NULL::DATE AS "expiration", NULL::VARCHAR AS "side", NULL::DOUBLE AS "strike", NULL::VARCHAR AS "added_ny", NULL::VARCHAR AS "note" WHERE 1=0;

-- files: קובצי הנתונים של מאגר האופציות — מהמניפסט (`manifest.json`): הכיסוי והאיכות של כל קובץ, בלי לפתוח אותו
CREATE OR REPLACE VIEW files AS WITH m AS (SELECT content::JSON AS j FROM read_text('<OPTIONS_DIR>/manifest.json')), f AS (SELECT unnest(map_entries(CAST(j -> '$.files' AS MAP(VARCHAR, JSON)))) AS e FROM m), g AS (SELECT e.key AS file, json_transform(e.value, '{"symbol": "VARCHAR", "kind": "VARCHAR", "month": "VARCHAR", "sessions": "BIGINT", "rows": "BIGINT", "first_session": "DATE", "last_session": "DATE", "complete": "BOOLEAN", "oi_rows_pct": "DOUBLE", "spot_sources": {"stock_eod_raw": "BIGINT", "candles_30m": "BIGINT", "parity": "BIGINT", "none": "BIGINT"}, "contracts_per_day_median": "DOUBLE", "contracts_per_day_median_total": "DOUBLE", "alarm": {"count": "BIGINT", "max": "BIGINT"}, "filter_version": "BIGINT", "retention": "VARCHAR", "updated_ny": "VARCHAR"}') AS s FROM f) SELECT CAST(file AS VARCHAR) AS "file", CAST(struct_extract(s, 'symbol') AS VARCHAR) AS "symbol", CAST(struct_extract(s, 'kind') AS VARCHAR) AS "data_kind", CAST(struct_extract(s, 'month') AS VARCHAR) AS "month", CAST(struct_extract(s, 'sessions') AS BIGINT) AS "sessions", CAST(struct_extract(s, 'rows') AS BIGINT) AS "rows", CAST(struct_extract(s, 'first_session') AS DATE) AS "first_session", CAST(struct_extract(s, 'last_session') AS DATE) AS "last_session", CAST(struct_extract(s, 'complete') AS BOOLEAN) AS "complete", CAST(struct_extract(s, 'oi_rows_pct') AS DOUBLE) AS "oi_rows_pct", CAST(struct_extract(struct_extract(s, 'spot_sources'), 'stock_eod_raw') AS BIGINT) AS "spot_stock_eod_raw", CAST(struct_extract(struct_extract(s, 'spot_sources'), 'candles_30m') AS BIGINT) AS "spot_candles_30m", CAST(struct_extract(struct_extract(s, 'spot_sources'), 'parity') AS BIGINT) AS "spot_parity", CAST(struct_extract(struct_extract(s, 'spot_sources'), 'none') AS BIGINT) AS "spot_none", CAST(struct_extract(s, 'contracts_per_day_median') AS DOUBLE) AS "contracts_median", CAST(struct_extract(s, 'contracts_per_day_median_total') AS DOUBLE) AS "contracts_median_total", CAST(struct_extract(struct_extract(s, 'alarm'), 'count') AS BIGINT) AS "alarm_count", CAST(struct_extract(struct_extract(s, 'alarm'), 'max') AS BIGINT) AS "alarm_max", CAST(struct_extract(s, 'filter_version') AS BIGINT) AS "filter_version", CAST(struct_extract(s, 'retention') AS VARCHAR) AS "retention", CAST(struct_extract(s, 'updated_ny') AS VARCHAR) AS "updated_ny" FROM g;
-- אין קבצים: CREATE OR REPLACE VIEW files AS SELECT NULL::VARCHAR AS "file", NULL::VARCHAR AS "symbol", NULL::VARCHAR AS "data_kind", NULL::VARCHAR AS "month", NULL::BIGINT AS "sessions", NULL::BIGINT AS "rows", NULL::DATE AS "first_session", NULL::DATE AS "last_session", NULL::BOOLEAN AS "complete", NULL::DOUBLE AS "oi_rows_pct", NULL::BIGINT AS "spot_stock_eod_raw", NULL::BIGINT AS "spot_candles_30m", NULL::BIGINT AS "spot_parity", NULL::BIGINT AS "spot_none", NULL::DOUBLE AS "contracts_median", NULL::DOUBLE AS "contracts_median_total", NULL::BIGINT AS "alarm_count", NULL::BIGINT AS "alarm_max", NULL::BIGINT AS "filter_version", NULL::VARCHAR AS "retention", NULL::VARCHAR AS "updated_ny" WHERE 1=0;

-- known_gaps: החורים הידועים — מהמניפסט, עם הסיבה: ימי מסחר (`point` ריק) ונקודות תוך-יומיות שהספק נשאל עליהם ולא החזיר, **ונקודות אחרי הסגירה ביום מסחר מקוצר** (13:30, 15:30 — הספק לא נשאל)
CREATE OR REPLACE VIEW known_gaps AS WITH m AS (SELECT content::JSON AS j FROM read_text('<OPTIONS_DIR>/manifest.json')), s AS (SELECT unnest(map_entries(CAST(j -> '$.symbols' AS MAP(VARCHAR, JSON)))) AS e FROM m), k AS (SELECT e.key AS symbol, unnest(['eod', 'intraday']) AS data_kind, e.value AS sv FROM s), mo AS (SELECT symbol, data_kind, unnest(map_values(TRY_CAST(json_extract(sv, '$.' || data_kind || '.known_gaps') AS MAP(VARCHAR, JSON)))) AS mv FROM k), d AS (SELECT symbol, data_kind, unnest(map_entries(TRY_CAST(mv AS MAP(VARCHAR, VARCHAR)))) AS e FROM mo), f AS (SELECT unnest(map_values(CAST(j -> '$.files' AS MAP(VARCHAR, JSON)))) AS fv FROM m), pd AS (SELECT fv ->> 'symbol' AS symbol, fv ->> 'kind' AS data_kind, unnest(map_entries(TRY_CAST(fv -> 'point_gaps' AS MAP(VARCHAR, MAP(VARCHAR, VARCHAR))))) AS e FROM f), pp AS (SELECT symbol, data_kind, e.key AS day, unnest(map_entries(e.value)) AS p FROM pd) SELECT symbol::VARCHAR AS symbol, data_kind::VARCHAR AS data_kind, CAST(e.key AS DATE) AS gap_date, NULL::VARCHAR AS point, e.value::VARCHAR AS reason FROM d UNION ALL SELECT symbol::VARCHAR, data_kind::VARCHAR, CAST(day AS DATE), p.key::VARCHAR, p.value::VARCHAR FROM pp;
-- אין קבצים: CREATE OR REPLACE VIEW known_gaps AS SELECT NULL::VARCHAR AS "symbol", NULL::VARCHAR AS "data_kind", NULL::DATE AS "gap_date", NULL::VARCHAR AS "point", NULL::VARCHAR AS "reason" WHERE 1=0;

-- earnings: תאריכי הדוחות הרבעוניים — מאגר נתוני השוק, `earnings/<סמל>.csv` (הפקודה `earnings`, MarketData). **הנתון של הספק כמות שהוא — לא לקרוא ממנו ישירות:** הספק טועה בכמה אחוזים מהשורות (X17) — קוראים מ-`earnings_checked`. **המגבלה:** תאריכי הפרסום בפועל כפי שידועים ביום השליפה (`fetched_ny`) — טובים לסימון בדיעבד של ימים סביב דוח; אינם 'מה שהיה ידוע מראש'. שורה `kind` = 'צפוי — לא סופי' היא הערכה של הספק. הספק נותן כחמש שנים אחורה. לקרנות סל אין דוחות (קובץ עם כותרת בלבד). יום ההשפעה של דוח: 'before open' — `report_date`, **וביום שאינו יום מסחר — יום המסחר הבא** (סבב 3ה); 'after close' — יום המסחר **הבא** (לפי לוח המסחר — `candles_daily` של SPY; ואם התאריך מחוץ ללוח — היום הבא שאינו שבת / ראשון); 'during market hours', 'לא ידוע' או ערך אחר — **שעה לא ידועה** (`time_known` = false; ב-`earnings_checked` — חלון של 15 ימי המסחר שלפני `report_date` ועד יום המסחר שאחריו). 'during market hours' הוא אצל הספק "שעה לא ידועה", ובשורות כאלה גם התאריך חשוד (X17). ההשוואה מנורמלת (אותיות קטנות, בלי רווחים בקצוות) ומכירה גם 'bmo' / 'before-market' / 'pre-market' ו-'amc' / 'after-market' / 'post-market'. (שאילתה 8; חלונות 'ייתכן דוח' — שאילתה 9). בלי התיקייה — ריקה
CREATE OR REPLACE VIEW earnings AS SELECT *, coalesce(lower(trim(report_time)) IN ('before open', 'bmo', 'before-market', 'pre-market', 'after close', 'amc', 'after-market', 'post-market'), false) AS time_known FROM read_csv('<MARKET_DIR>/earnings/*.csv', header=true, columns={'symbol': 'VARCHAR', 'report_date': 'DATE', 'report_time': 'VARCHAR', 'fiscal_year': 'BIGINT', 'fiscal_quarter': 'BIGINT', 'updated': 'VARCHAR', 'kind': 'VARCHAR', 'fetched_ny': 'VARCHAR', 'source': 'VARCHAR'});
-- אין קבצים: CREATE OR REPLACE VIEW earnings AS SELECT NULL::VARCHAR AS "symbol", NULL::DATE AS "report_date", NULL::VARCHAR AS "report_time", NULL::BIGINT AS "fiscal_year", NULL::BIGINT AS "fiscal_quarter", NULL::VARCHAR AS "updated", NULL::VARCHAR AS "kind", NULL::VARCHAR AS "fetched_ny", NULL::VARCHAR AS "source", NULL::BOOLEAN AS "time_known" WHERE 1=0;

-- known_exceptions: **רשימת החריגים הסגורה** — מאגר האופציות, `catalog/known_exceptions.csv` (נכתב מהכיול, `known_exceptions`): מה ידוע כחריג בנתון, מה זה עושה ומה לעשות. תיעוד בלבד — אף נתון אינו משתנה לפיה
CREATE OR REPLACE VIEW known_exceptions AS SELECT * FROM read_csv('<OPTIONS_DIR>/catalog/known_exceptions.csv', header=true, columns={'id': 'VARCHAR', 'scope': 'VARCHAR', 'symbols': 'VARCHAR', 'date_from': 'DATE', 'date_to': 'DATE', 'field': 'VARCHAR', 'stored': 'DOUBLE', 'correct': 'DOUBLE', 'correct_30m': 'DOUBLE', 'what': 'VARCHAR', 'effect': 'VARCHAR', 'guidance': 'VARCHAR'});
-- אין קבצים: CREATE OR REPLACE VIEW known_exceptions AS SELECT NULL::VARCHAR AS "id", NULL::VARCHAR AS "scope", NULL::VARCHAR AS "symbols", NULL::DATE AS "date_from", NULL::DATE AS "date_to", NULL::VARCHAR AS "field", NULL::DOUBLE AS "stored", NULL::DOUBLE AS "correct", NULL::DOUBLE AS "correct_30m", NULL::VARCHAR AS "what", NULL::VARCHAR AS "effect", NULL::VARCHAR AS "guidance" WHERE 1=0;

-- earnings_corrections: **טבלת התיקונים של תאריכי הדוחות** — מאגר האופציות, `catalog/earnings_corrections.csv` (נכתב מהכיול, `earnings_corrections`, בפקודה `catalog`): שורה לכל דוח שנבדק — תוקן או תואם לספק (אומת מול הודעת החברה), או שאינו דוח; "מוצע" / "חשוד" — לבדיקות עתידיות. הנתון של הספק (`earnings`) בעינו — התיקון מוחל בתצוגה `earnings_checked`
CREATE OR REPLACE VIEW earnings_corrections AS SELECT * FROM read_csv('<OPTIONS_DIR>/catalog/earnings_corrections.csv', header=true, columns={'symbol': 'VARCHAR', 'fiscal_year': 'BIGINT', 'fiscal_quarter': 'BIGINT', 'stored_date': 'DATE', 'stored_time': 'VARCHAR', 'verified_date': 'DATE', 'verified_time': 'VARCHAR', 'status': 'VARCHAR', 'confidence': 'VARCHAR', 'source': 'VARCHAR', 'note': 'VARCHAR'});
-- אין קבצים: CREATE OR REPLACE VIEW earnings_corrections AS SELECT NULL::VARCHAR AS "symbol", NULL::BIGINT AS "fiscal_year", NULL::BIGINT AS "fiscal_quarter", NULL::DATE AS "stored_date", NULL::VARCHAR AS "stored_time", NULL::DATE AS "verified_date", NULL::VARCHAR AS "verified_time", NULL::VARCHAR AS "status", NULL::VARCHAR AS "confidence", NULL::VARCHAR AS "source", NULL::VARCHAR AS "note" WHERE 1=0;

-- options_eod_uid: `options_eod` ועוד `contract_uid`. **מזהה יציב לחוזה** שאינו משתנה בפיצול (תצוגה נגזרת; `options_eod` בעינה). **סיכונים:** QQQ / COST סביב 27/12/2023 אינם מגושרים (X01); מזהה יכול לחזור כחוזה אחר אחרי פיצול. כבד על כל המאגר — לסנן לפי `symbol`
CREATE OR REPLACE VIEW options_eod_uid AS SELECT e.*, e.symbol || '|' || strftime(e.expiration, '%Y%m%d') || '|' || e.side || '|' || printf('%.2f', round(e.strike / coalesce(f.factor, 1), 2)) AS contract_uid FROM options_eod e LEFT JOIN LATERAL (SELECT exp(sum(ln(a.ratio))) AS factor FROM corporate_actions a WHERE a.symbol = e.symbol AND a.date > e.session) f ON TRUE;

-- earnings_checked: **תאריכי הדוחות אחרי שכבת התיקונים — מכאן קוראים** (תצוגה נגזרת: `earnings` + `earnings_corrections` + לוח המסחר; בלי `earnings/` — ריקה). **לקרוא רק מ-`earnings_checked`; לכל החלטה — לפי `effect_day_from` / `effect_day_to`; מחקר שדורש ודאות — רק שורות `reliable`** (עומדות בכלל האמינות); **מחקר שדורש אימות מול מקור — רק `externally_verified`**; הפירוט שורה-שורה — `earnings_corrections`. החלון 'ייתכן דוח' (`effect_day_from` … `effect_day_to`, ימי מסחר לפי `candles_daily` של SPY; מחוץ ללוח — לפי ימי השבוע): **"כפי שהספק מסר" / "אומת — תואם לספק" / "תוקן — אומת מול הודעת החברה" עם שעה ידועה** — יום ההשפעה בלבד (לפני הפתיחה ⇒ היום, וביום שאינו יום מסחר — יום המסחר הבא; אחרי הסגירה ⇒ יום המסחר הבא); **"תוקן — מוצע, טרם אומת חיצונית"** — **אינו מצמצם** (סבב 3ה): איחוד של החלון שהשורה הייתה מקבלת בלי התיקון (שעה ידועה אצל הספק — יום ההשפעה; שעה לא ידועה — 15 ימי המסחר עד יום המסחר שאחריו) ושל החלון לפי התיקון (יום ההשפעה המתוקן; תיקון בלי שעה — שני הימים), עד שהתיקון מאומת; **"חשוד — טרם אומת" ו"שעה לא ידועה"** — 15 ימי המסחר שלפני `report_date` ועד יום המסחר שאחריו; **"לא דוח"** — ריקים (`is_report` = false). **'צפוי — לא סופי':** החלון לפי אותו כלל — אבל חלון של שורת 'צפוי' הוא ההערכה של הספק בלבד — התאריך עשוי לזוז; אין להסיק ממנו 'אין דוח עד הפקיעה'. `reliable` = true רק ל-"תוקן — אומת מול הודעת החברה" / "אומת — תואם לספק" / "כפי שהספק מסר" עם שעה ידועה **וגם** `kind` = 'פורסם' — "מוצע", "חשוד", שעה לא ידועה ו'צפוי — לא סופי' אינם אמינים. תיקון חל רק כשהשורה של הספק עדיין זהה למה שנבדק (`stored_date` / `stored_time`); אם הספק שינה אותה — התיקון אינו מוחל (`catalog` אומר זאת ומסתיים בקוד 9).
CREATE OR REPLACE VIEW earnings_checked AS WITH cal AS (SELECT DISTINCT session AS day FROM candles_daily WHERE symbol = 'SPY'), caln AS (SELECT day, row_number() OVER (ORDER BY day) AS n FROM cal), b AS (SELECT min(day) AS d0, max(day) AS d1 FROM cal), j AS (SELECT e.*, c.status AS c_status, c.verified_date AS c_date, nullif(trim(c.verified_time), '') AS c_time FROM earnings e LEFT JOIN earnings_corrections c ON c.symbol = e.symbol AND c.stored_date = e.report_date AND lower(trim(c.stored_time)) = lower(trim(e.report_time)) AND ((c.fiscal_year IS NOT NULL AND c.fiscal_year = e.fiscal_year AND c.fiscal_quarter = e.fiscal_quarter) OR (c.fiscal_year IS NULL AND (e.fiscal_year IS NULL OR e.fiscal_quarter IS NULL)))), s AS (SELECT j.symbol, j.report_date, j.report_time, j.fiscal_year, j.fiscal_quarter, j.updated, j.kind, j.fetched_ny, j.source, j.time_known, coalesce(j.c_status, CASE WHEN j.time_known THEN 'כפי שהספק מסר' ELSE 'שעה לא ידועה' END) AS check_status, CASE WHEN lower(trim(j.report_time)) IN ('before open', 'bmo', 'before-market', 'pre-market') THEN 'before open' WHEN lower(trim(j.report_time)) IN ('after close', 'amc', 'after-market', 'post-market') THEN 'after close' END AS v_time, j.c_date, j.c_time FROM j), t AS (SELECT s.*, CASE WHEN check_status LIKE 'תוקן%' THEN c_date ELSE report_date END AS report_date_checked, CASE WHEN check_status LIKE 'תוקן%' THEN c_time ELSE v_time END AS report_time_checked FROM s), u AS (SELECT t.*, CASE WHEN t.report_date >= b.d0 AND t.report_date < b.d1 THEN (SELECT min(day) FROM cal WHERE day > t.report_date) ELSE t.report_date + CASE dayofweek(t.report_date) WHEN 5 THEN 3 WHEN 6 THEN 2 ELSE 1 END END AS nx_v, CASE WHEN t.report_date_checked >= b.d0 AND t.report_date_checked < b.d1 THEN (SELECT min(day) FROM cal WHERE day > t.report_date_checked) ELSE t.report_date_checked + CASE dayofweek(t.report_date_checked) WHEN 5 THEN 3 WHEN 6 THEN 2 ELSE 1 END END AS nx_c, CASE WHEN t.report_date >= b.d0 AND t.report_date <= b.d1 THEN (SELECT min(day) FROM cal WHERE day >= t.report_date) ELSE t.report_date + CASE dayofweek(t.report_date) WHEN 6 THEN 2 WHEN 0 THEN 1 ELSE 0 END END AS on_v, CASE WHEN t.report_date_checked >= b.d0 AND t.report_date_checked <= b.d1 THEN (SELECT min(day) FROM cal WHERE day >= t.report_date_checked) ELSE t.report_date_checked + CASE dayofweek(t.report_date_checked) WHEN 6 THEN 2 WHEN 0 THEN 1 ELSE 0 END END AS on_c, CASE WHEN t.report_date_checked >= b.d0 AND t.report_date_checked <= b.d1 THEN (SELECT min(n) FROM caln WHERE day >= t.report_date_checked) END AS n0, CASE WHEN t.report_date >= b.d0 AND t.report_date <= b.d1 THEN (SELECT min(n) FROM caln WHERE day >= t.report_date) END AS n0_v FROM t, b), w AS (SELECT u.*, CASE WHEN v_time = 'after close' THEN nx_v WHEN v_time = 'before open' THEN on_v ELSE report_date END AS lo_v, CASE WHEN v_time = 'before open' THEN on_v ELSE nx_v END AS hi_v, CASE WHEN report_time_checked = 'after close' THEN nx_c WHEN report_time_checked = 'before open' THEN on_c ELSE report_date_checked END AS lo_c, CASE WHEN report_time_checked = 'before open' THEN on_c ELSE nx_c END AS hi_c, CASE WHEN u.n0 > 15 THEN (SELECT day FROM caln WHERE n = u.n0 - 15) ELSE report_date_checked - 21 END AS back_c, CASE WHEN u.n0_v > 15 THEN (SELECT day FROM caln WHERE n = u.n0_v - 15) ELSE report_date - 21 END AS back_v FROM u) SELECT symbol, report_date, report_time, fiscal_year, fiscal_quarter, updated, kind, fetched_ny, source, time_known, check_status::VARCHAR AS check_status, report_date_checked::DATE AS report_date_checked, report_time_checked::VARCHAR AS report_time_checked, (check_status <> 'לא דוח') AS is_report, (check_status IN ('תוקן — אומת מול הודעת החברה', 'אומת — תואם לספק', 'כפי שהספק מסר') AND report_time_checked IS NOT NULL AND coalesce(kind = 'פורסם', false)) AS reliable, CAST(CASE WHEN check_status = 'לא דוח' THEN NULL WHEN check_status = 'תוקן — מוצע, טרם אומת חיצונית' THEN least(CASE WHEN v_time IS NULL THEN back_v ELSE lo_v END, lo_c) WHEN check_status = 'חשוד — טרם אומת' OR report_time_checked IS NULL THEN back_c ELSE lo_c END AS DATE) AS effect_day_from, CAST(CASE WHEN check_status = 'לא דוח' THEN NULL WHEN check_status = 'תוקן — מוצע, טרם אומת חיצונית' THEN greatest(hi_v, hi_c) WHEN check_status = 'חשוד — טרם אומת' OR report_time_checked IS NULL THEN nx_c ELSE hi_c END AS DATE) AS effect_day_to, coalesce(check_status IN ('תוקן — אומת מול הודעת החברה', 'אומת — תואם לספק'), false) AS externally_verified FROM w;

-- catalog_info: גרסת המבנה, השעה, **התגית של המאגר הסגור ותאריך הסגירה** (נכתבו בפקודה `catalog`)
CREATE OR REPLACE VIEW catalog_info AS SELECT 'options-data/1' AS schema, current_timestamp AS built_at, NULL::VARCHAR AS closed_tag, NULL::DATE AS closed_through;
